import { useLayoutEffect, useRef, useState } from 'react';
import { List, X } from 'react-bootstrap-icons';

const navLinks = [
  { href: "#about", label: "About" },
  { href: "#gallery", label: "Gallery" },
  { href: "#projects", label: "Projects" },
  { href: "#experience", label: "Experience" },
  { href: "#skills", label: "Skills" },
  { href: "#publications", label: "Research" },
  { href: "#contact", label: "Contact" },
];

export const NavBar = () => {
  const navRef = useRef(null);
  const [isOpen, setIsOpen] = useState(false);

  useLayoutEffect(() => {
    const setNavHeight = () => {
      if (navRef.current) {
        document.documentElement.style.setProperty('--nav-h', `${navRef.current.offsetHeight}px`);
      }
    };
    setNavHeight();
    window.addEventListener('resize', setNavHeight);
    return () => window.removeEventListener('resize', setNavHeight);
  }, []);

  useLayoutEffect(() => {
    const closeOnWideView = () => {
      if (window.innerWidth > 780) setIsOpen(false);
    };
    window.addEventListener('resize', closeOnWideView);
    return () => window.removeEventListener('resize', closeOnWideView);
  }, []);

  return (
    <nav className={`site-nav ${isOpen ? 'is-open' : ''}`} ref={navRef}>
      <a href="#home" className="site-nav-brand" onClick={() => setIsOpen(false)}>Pranav Upreti</a>
      <button
        type="button"
        className="site-nav-toggle"
        aria-label={isOpen ? "Close menu" : "Open menu"}
        aria-expanded={isOpen}
        onClick={() => setIsOpen((open) => !open)}
      >
        {isOpen ? <X size={26} /> : <List size={26} />}
      </button>
      <div className="site-nav-links">
        {navLinks.map((link) => (
          <a
            key={link.href}
            href={link.href}
            className="site-nav-link"
            onClick={() => setIsOpen(false)}
          >
            {link.label}
          </a>
        ))}
      </div>
    </nav>
  );
};
